import{_ as a,o as n,c as t,a3 as i}from"./chunks/framework.MGD2uYU7.js";const r=JSON.parse('{"title":"SC-03 — Chi tiết tin","description":"","frontmatter":{"title":"SC-03 — Chi tiết tin"},"headers":[],"relativePath":"wireframes/public/sc-03-chi-tiet-tin.md","filePath":"wireframes/public/sc-03-chi-tiet-tin.md","lastUpdated":null}'),l={name:"wireframes/public/sc-03-chi-tiet-tin.md"};function c(p,s,e,d,h,o){return n(),t("div",null,[...s[0]||(s[0]=[i('<h1 id="sc-03-—-chi-tiet-tin-đang" tabindex="-1">SC-03 — Chi tiết tin đăng <a class="header-anchor" href="#sc-03-—-chi-tiet-tin-đang" aria-label="Permalink to &quot;SC-03 — Chi tiết tin đăng&quot;">​</a></h1><p><span class="wf-badge warn">MÀN PHỨC TẠP CAO</span> <span class="wf-badge info">Route: /nha-o-xa-hoi/[id]</span> <span class="wf-badge muted">Nguồn: docs/05 §3 SC-03 · docs/03 UC-03/UC-04 · docs/02 FR-HS-07 · docs/08 BR-KYC-08/BR-HS-12</span></p><p><strong>Ai xem màn này</strong>: Guest (xem công khai) · Người mua đã KYC (đặt lịch xem) · Chính chủ tin (thêm tab quản trị + dữ liệu nhạy cảm) · Người theo dõi phiên (tin RESERVED). <strong>Mục đích / cảm xúc thiết kế</strong>: trang &quot;chốt niềm tin&quot; — ảnh thật, thông số thật, pháp lý đã xác minh, giá minh bạch kèm đơn giá /m² so với giá trần dự án. CTA thay đổi theo <strong>người xem × trạng thái tin</strong> (5 biến thể ở mục 4). <strong>Ví dụ số dùng trong bản vẽ</strong>: căn <code>CT2-A18.05</code> · NOXH <code>HP-380</code> (Vĩnh Niệm, Lê Chân, Hải Phòng) · <code>72 m² · 2 PN · 1 WC · tầng 18 · Sổ hồng</code> · giá <code>1.250.000.000 ₫</code> (= <code>17.361.111 ₫/m²</code>) · trần dự án <code>30.000.000 ₫/m²</code>.</p><h2 id="_1-desktop-—-gallery-thong-so-panel-cta-nguoi-mua-đa-kyc-tin-listed" tabindex="-1">1. Desktop — gallery + thông số + panel CTA (người mua đã KYC, tin LISTED) <a class="header-anchor" href="#_1-desktop-—-gallery-thong-so-panel-cta-nguoi-mua-đa-kyc-tin-listed" aria-label="Permalink to &quot;1. Desktop — gallery + thông số + panel CTA (người mua đã KYC, tin LISTED)&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/nha-o-xa-hoi/lst_01JZK3M9W2Q8T1V5X7Y9ZBCD</span></div><div class="wf-body"><div class="wf-header"><span class="wf-logo">AnPhuc</span><span class="wf-nav"><span class="active">Mua nhà</span><span>Đấu giá</span><span>Bảng gói</span><span>Hướng dẫn</span></span><span class="wf-header-actions"><span class="wf-bell">🔔<span class="count">2</span></span><span class="wf-avatar">NA</span></span></div><div class="wf-container"><div class="wf-breadcrumb">Mua nhà › NOXH HP-380 › <b>Căn CT2-A18.05</b></div><div class="wf-row" style="align-items:flex-start;"><div class="wf-grow wf-col" style="gap:12px;"><div class="wf-row between middle"><span class="wf-title xl">Căn CT2-A18.05 — NOXH HP-380 <span class="wf-callout">1</span></span><span class="wf-badge ok">ĐANG BÁN</span></div><div class="wf-img" style="min-height:320px;"><span>ẢNH CHÍNH 4:3 — click mở lightbox <span class="wf-callout">2</span></span></div><div class="wf-row" style="gap:8px;"><div class="wf-img" style="flex:1;min-height:64px;"><span>1</span></div><div class="wf-img" style="flex:1;min-height:64px;"><span>2</span></div><div class="wf-img" style="flex:1;min-height:64px;"><span>3</span></div><div class="wf-img" style="flex:1;min-height:64px;"><span>4</span></div><div class="wf-img" style="flex:1;min-height:64px;border-style:dashed;"><span>+8 ảnh</span></div></div><div class="wf-card flat"><div class="pad wf-col" style="gap:8px;"><span class="wf-title">Thông số căn hộ</span><table class="wf-table"><tbody><tr><td>Diện tích</td><td><b>72 m²</b> (trong chuẩn 15–500 m²)</td><td>Phòng ngủ</td><td><b>2 PN</b></td></tr><tr><td>WC</td><td><b>1</b></td><td>Tầng</td><td><b>18</b></td></tr><tr><td>Pháp lý</td><td><b>Sổ hồng</b> · Đã xác minh pháp lý ✓ <span class="wf-callout">3</span></td><td>Mã tin</td><td>lst_01JZK3M9… (đăng 02/10/2026 08:00 GMT+7)</td></tr></tbody></table></div></div><div class="wf-card flat"><div class="pad wf-col" style="gap:8px;"><span class="wf-title">Mô tả</span><div class="wf-lines"><span class="w-100"></span><span class="w-90"></span><span class="w-100"></span><span class="w-60"></span></div><span class="wf-small">Nội dung do chủ nhà viết, ADMIN đã đối chiếu khi duyệt (ảnh đúng căn, giá không vượt trần — BR-HS-02/06/07).</span></div></div><div class="wf-card flat"><div class="pad wf-col" style="gap:8px;"><div class="wf-row between middle"><span class="wf-title">Dự án NOXH HP-380 <span class="wf-callout">4</span></span><span class="wf-small wf-accent">Xem chi tiết dự án → SC-04</span></div><span class="wf-text">380 Võ Nguyên Giáp · Vĩnh Niệm · Lê Chân · Hải Phòng</span><div class="wf-img" style="min-height:140px;"><span>BẢN ĐỒ VỊ TRÍ (map placeholder — v1 chưa có GPS, chỉ khối địa chỉ)</span></div><div class="wf-row wrap" style="gap:6px;"><span class="wf-badge muted">480 căn</span><span class="wf-badge muted">15 tầng</span><span class="wf-badge muted">Bàn giao 2027</span><span class="wf-badge info">Đủ điều kiện bán</span></div></div></div><div class="wf-card flat"><div class="pad wf-row middle between"><div class="wf-col" style="gap:2px;"><span class="wf-title">Chủ nhà đã xác minh ✓ <span class="wf-callout">5</span></span><span class="wf-small">Danh tính ẩn với người xem · KYC APPROVED · tên trên sổ khớp hồ sơ</span></div><span class="wf-avatar" style="width:40px;height:40px;">👤</span></div></div></div><div style="width:320px;flex:none;" class="wf-col"><div class="wf-card" style="border-width:2px;border-color:var(--wf-line-strong);"><div class="pad wf-col" style="gap:10px;"><span class="wf-money lg">1.250.000.000 ₫ <span class="wf-callout">6</span></span><div class="wf-row between"><span class="wf-text">Đơn giá</span><span class="wf-money">17.361.111 ₫/m²</span></div><div class="wf-row between"><span class="wf-text">Trần bán lại dự án</span><span class="wf-money">30.000.000 ₫/m²</span></div><div class="wf-note" style="background:var(--wf-ok-soft);border-color:var(--wf-ok);color:var(--wf-ok);margin:0;">✓ Không vượt giá trần NOXH của dự án theo quy định <span class="wf-callout">7</span></div><span class="wf-btn primary lg block">Đặt lịch xem nhà <span class="wf-callout" style="background:#fff;color:var(--wf-accent);">8</span></span><span class="wf-btn ghost block">Lưu tin (nhận thông báo khi đổi trạng thái)</span><span class="wf-small wf-center">Mọi trao đổi qua nền tảng — không chuyển tiền ngoài hệ thống</span></div></div><div class="wf-card flat"><div class="pad wf-col" style="gap:6px;"><span class="wf-title">Quy tắc đặt lịch <span class="wf-callout">9</span></span><span class="wf-small">· Slot sớm nhất: sau 24 giờ · xa nhất: trong 14 ngày</span><span class="wf-small">· Khung giờ 08:00–20:00 (GMT+7)</span><span class="wf-small">· Tối đa 3 lịch đang chờ cho mỗi người</span><span class="wf-small">· Chủ nhà phản hồi trong 24h (SLA ops)</span></div></div></div></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/05 §3 SC-03 · docs/03 UC-03/UC-04 · docs/08)</div><ol><li><span class="num">1</span><span>Chỉ tin `LISTED / RESERVED / SOLD` xem được public; badge trạng thái tương ứng Đang bán (xanh) / Sắp đấu giá (xám) / Đã bán (muted, phủ mờ gallery + CTA thay bằng &quot;Xem tin tương tự&quot;). <span class="ref">FR-HS-07</span> <span class="ref">docs/07 §3</span></span></li><li><span class="num">2</span><span>Gallery 3–15 ảnh (BR-HS-10); thumb cuộn ngang, click ảnh chính hoặc thumb → lightbox (mục 2). Alt text bắt buộc cho accessibility. Ảnh chỉ serve public khi tin đã LISTED. <span class="ref">BR-HS-10</span> <span class="ref">FR-HS-08</span></span></li><li><span class="num">3</span><span><b>Không bao giờ lộ certSerial / tài liệu pháp lý</b> cho người không phải chủ — payload public chỉ có `legalVerified: true` + `legalType`. Số sổ chỉ chủ tin thấy (masked, mục 4 biến thể E). <span class="ref">BR-HS-12</span> <span class="ref">docs/06 §4.1</span></span></li><li><span class="num">4</span><span>Khối dự án lấy từ `GET /projects/{id}` (badge legalStatus SALES_ELIGIBLE = &quot;Đủ điều kiện bán&quot;). Map là placeholder khối địa chỉ — <b>v1 chưa có GPS, không mock bản đồ thật</b>. <span class="ref">docs/06 §4.10</span></span></li><li><span class="num">5</span><span>Chủ nhà hiển thị <b>ẩn danh</b>: &quot;Chủ nhà đã xác minh ✓&quot; — không tên, không SĐT, không ảnh. Liên hệ duy nhất = đặt lịch xem qua nền tảng. <span class="ref">UC-03</span> <span class="ref">docs/05 §3</span></span></li><li><span class="num">6</span><span>Giá rao + <b>đơn giá /m² luôn hiện cạnh nhau</b> (quy tắc &quot;không số gộp&quot; — docs/05 §1.6): người mua tự so sánh được với trần dự án và các tin cùng khu. <span class="ref">docs/05 §1.6</span></span></li><li><span class="num">7</span><span>Dòng ✓ xanh xác nhận đơn giá ≤ `resalePriceCapM2` — BE enforce lúc submit &amp; lúc duyệt, FE chỉ hiển thị để tăng niềm tin. Lỗi phía đăng tin: &quot;Giá vượt trần {cap} ₫/m² của dự án theo quy định&quot;. <span class="ref">BR-HS-06</span> <span class="ref">docs/06 §5</span></span></li><li><span class="num">8</span><span><b>CTA chính đổi theo người xem × trạng thái tin</b> — 5 biến thể vẽ ở mục 4. Ở bản này (USER KYC APPROVED + tin LISTED) → mở form đặt lịch SC-27 inline/drawer. <span class="ref">BR-KYC-08</span> <span class="ref">FR-VW-01</span></span></li><li><span class="num">9</span><span>Panel quy tắc đặt lịch hiện tĩnh để user không bất ngờ khi validate: lỗi field dùng đúng copy &quot;Chọn lịch trước 24h và trong 14 ngày (08:00–20:00)&quot; và &quot;Tối đa 3 lịch chờ — hủy lịch cũ để đặt mới&quot;. <span class="ref">BR-VW-01/02</span> <span class="ref">docs/06 §5</span></span></li></ol></div><h2 id="_2-lightbox-anh-modal" tabindex="-1">2. Lightbox ảnh (modal) <a class="header-anchor" href="#_2-lightbox-anh-modal" aria-label="Permalink to &quot;2. Lightbox ảnh (modal)&quot;">​</a></h2><div class="wf"><div class="wf-modal-overlay"><div class="wf-modal" style="max-width:640px;"><div class="head wf-row between middle"><span>Ảnh 3 / 12 — Căn CT2-A18.05</span><span class="wf-btn sm ghost">Đóng ✕ <span class="wf-callout">10</span></span></div><div class="wf-img" style="min-height:300px;"><span>ẢNH PHÓNG TO</span></div><div class="wf-row between middle" style="margin-top:10px;"><span class="wf-btn">‹ Trước</span><span class="wf-row" style="gap:6px;"><div class="wf-img" style="width:52px;min-height:40px;"><span>2</span></div><div class="wf-img" style="width:52px;min-height:40px;border-color:var(--wf-accent);border-width:2px;"><span>3</span></div><div class="wf-img" style="width:52px;min-height:40px;"><span>4</span></div></span><span class="wf-btn">Sau ›</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">10</span><span>Lightbox: phím ←/→ chuyển ảnh, Esc đóng, click nền đóng; body scroll khóa khi mở. Đếm &quot;Ảnh X / N&quot; để người xem biết đã xem hết chưa. Không zoom pinch trong v1 desktop (mobile browser tự xử). <span class="ref">docs/05 §1.7</span></span></li></ol></div><h2 id="_3-mobile-360px-—-1-cot-cta-sticky-đay" tabindex="-1">3. Mobile 360px — 1 cột, CTA sticky đáy <a class="header-anchor" href="#_3-mobile-360px-—-1-cot-cta-sticky-đay" aria-label="Permalink to &quot;3. Mobile 360px — 1 cột, CTA sticky đáy&quot;">​</a></h2><div class="wf"><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-bell">🔔<span class="count">2</span></span></div><div class="wf-container" style="padding:12px;"><div class="wf-img" style="min-height:200px;"><span>ẢNH CHÍNH — vuốt ngang xem 12 ảnh</span></div><div class="wf-row between middle" style="margin-top:10px;"><span class="wf-title lg">Căn CT2-A18.05</span><span class="wf-badge ok">ĐANG BÁN</span></div><span class="wf-text">NOXH HP-380 · Vĩnh Niệm, Lê Chân, Hải Phòng</span><div class="wf-card flat" style="margin-top:10px;"><div class="pad wf-col" style="gap:4px;"><div class="wf-row between"><span class="wf-text">Giá</span><span class="wf-money lg">1.250.000.000 ₫</span></div><div class="wf-row between"><span class="wf-text">Đơn giá</span><span class="wf-money">17.361.111 ₫/m²</span></div><div class="wf-row between"><span class="wf-text">Trần dự án</span><span class="wf-money">30.000.000 ₫/m²</span></div></div></div><div class="wf-row wrap" style="margin-top:10px;gap:6px;"><span class="wf-badge muted">72 m²</span><span class="wf-badge muted">2 PN</span><span class="wf-badge muted">1 WC</span><span class="wf-badge muted">tầng 18</span><span class="wf-badge ok">Sổ hồng ✓</span></div><div class="wf-card flat" style="margin-top:10px;"><div class="pad wf-row between middle"><div class="wf-col" style="gap:2px;"><span class="wf-title">Chủ nhà đã xác minh ✓</span><span class="wf-small">Danh tính ẩn · liên hệ qua nền tảng</span></div><span class="wf-avatar" style="width:36px;height:36px;">👤</span></div></div><div class="wf-card flat" style="margin-top:10px;"><div class="pad wf-col" style="gap:4px;"><span class="wf-title">Dự án NOXH HP-380</span><div class="wf-img" style="min-height:90px;"><span>BẢN ĐỒ (placeholder)</span></div><span class="wf-small wf-accent">Xem chi tiết dự án →</span></div></div></div><div style="position:sticky;bottom:0;background:#fff;border-top:1px solid var(--wf-line);padding:10px 12px;" class="wf-row middle"><div class="wf-col" style="flex:1;gap:0;"><span class="wf-money">1.250.000.000 ₫</span><span class="wf-small">17,4 tr/m² · 72 m²</span></div><span class="wf-btn primary">Đặt lịch xem <span class="wf-callout" style="background:#fff;color:var(--wf-accent);">11</span></span></div></div></div><div class="wf-legend"><div class="t">Chú thích mobile</div><ol><li><span class="num">11</span><span>Thanh CTA <b>sticky đáy</b>: luôn thấy giá + nút hành chính theo biến thể người xem (mục 4). Gallery thành carousel vuốt ngang, dot counter; bảng thông số thu thành badge row. Panel &quot;Quy tắc đặt lịch&quot; gộp vào form khi bấm CTA.</span></li></ol></div><h2 id="_4-cta-thay-đoi-theo-nguoi-xem-×-trang-thai-tin-—-5-bien-the" tabindex="-1">4. CTA thay đổi theo người xem × trạng thái tin — 5 biến thể <a class="header-anchor" href="#_4-cta-thay-đoi-theo-nguoi-xem-×-trang-thai-tin-—-5-bien-the" aria-label="Permalink to &quot;4. CTA thay đổi theo người xem × trạng thái tin — 5 biến thể&quot;">​</a></h2><div class="wf"><div class="wf-grid"><div class="wf-col"><span class="wf-state-label">A · GUEST + TIN LISTED</span><div class="wf-card" style="border-width:2px;border-color:var(--wf-line-strong);"><div class="pad wf-col" style="gap:8px;"><span class="wf-money lg">1.250.000.000 ₫</span><span class="wf-btn primary lg block">Đăng nhập để đặt lịch xem</span><span class="wf-small wf-center">Chưa có tài khoản? <b class="wf-accent">Đăng ký miễn phí</b> — chỉ cần email</span></div></div><span class="wf-small">Bấm CTA → SC-09 login kèm <b>intent deep-link return</b> về đúng tin này sau đăng nhập (AF-1 UC-03). Guest vẫn xem đủ ảnh/thông số/giá. <span class="wf-callout">12</span></span></div><div class="wf-col"><span class="wf-state-label">B · USER KYC ≠ APPROVED + LISTED</span><div class="wf-card" style="border-width:2px;border-color:var(--wf-line-strong);"><div class="pad wf-col" style="gap:8px;"><span class="wf-money lg">1.250.000.000 ₫</span><div class="wf-note" style="margin:0;">Bạn cần xác minh danh tính (CCCD) trước khi thao tác này</div><span class="wf-btn primary lg block">Đi xác minh → SC-21</span><span class="wf-small wf-center">Duyệt trong 48h (SLA) · sau đó đặt lịch được ngay</span></div></div><span class="wf-small">Message hiển thị = <b>nguyên văn</b> lỗi `KYC_REQUIRED` docs/06 §5; FE chặn sớm thay vì gọi API nhận 403. KYC PENDING → note đổi thành &quot;Hồ sơ đang chờ duyệt — quay lại sau&quot;. <span class="wf-callout">13</span></span></div><div class="wf-col"><span class="wf-state-label">C · USER KYC APPROVED + LISTED</span><div class="wf-card" style="border-width:2px;border-color:var(--wf-line-strong);"><div class="pad wf-col" style="gap:8px;"><span class="wf-money lg">1.250.000.000 ₫</span><span class="wf-btn primary lg block">Đặt lịch xem nhà</span><div class="wf-input">Chọn ngày/giờ (08:00–20:00) <span class="caret">📅</span></div><span class="wf-small">Sớm nhất: 11/10/2026 09:41 · bạn còn <b>3</b> lịch chờ khả dụng</span><span class="wf-btn block">Gửi yêu cầu</span></div></div><span class="wf-small">Slot picker chặn client-side ngày ngoài [now+24h, now+14d] và giờ ngoài 08:00–20:00; server re-check → 422 highlight field &quot;Chọn lịch trước 24h và trong 14 ngày (08:00–20:00)&quot;. Quá 3 lịch chờ → &quot;Tối đa 3 lịch chờ — hủy lịch cũ để đặt mới&quot;. <span class="wf-callout">14</span></span></div><div class="wf-col"><span class="wf-state-label">D · MỌI NGƯỜI XEM + TIN RESERVED (có phiên)</span><div class="wf-card" style="border-width:2px;border-color:var(--wf-danger);"><div class="pad wf-col" style="gap:8px;"><span class="wf-row between middle"><span class="wf-money lg">Khởi điểm 1.800.000.000 ₫</span><span class="wf-badge danger live">🔴 LIVE</span></span><span class="wf-text">Tin đang trong phiên đấu giá — giá rao không còn áp dụng. Cọc 90.000.000 ₫ · bước giá 18.000.000 ₫.</span><div class="wf-center"><span class="wf-countdown sm">00:14:32</span></div><span class="wf-btn danger lg block">Xem phiên đấu giá → SC-06</span><span class="wf-small wf-center">Đã đóng đăng ký (trước giờ mở 24h)</span></div></div><span class="wf-small">Nút đặt lịch <b>biến mất</b> (tin RESERVED không nhận lịch — 409). Dòng &quot;Đã đóng đăng ký…&quot; chỉ hiện khi qua regDeadline (copy 410 docs/06 §5); còn window → &quot;Đăng ký tham gia → SC-24&quot;. Phiên AWARDED/FAILED → tin về LISTED hoặc SOLD, CTA theo trạng thái mới. <span class="wf-callout">15</span></span></div><div class="wf-col"><span class="wf-state-label">E · CHÍNH CHỦ TIN (self-view)</span><div class="wf-card" style="border-width:2px;border-color:var(--wf-accent);"><div class="pad wf-col" style="gap:8px;"><div class="wf-tabs"><span class="wf-tab">Bản công khai</span><span class="wf-tab active">Quản trị tin của bạn</span></div><div class="wf-row between"><span class="wf-text">Sổ hồng (chỉ bạn thấy)</span><span class="wf-strong">SH-****4521 <span class="wf-callout">16</span></span></div><div class="wf-row between"><span class="wf-text">Trạng thái</span><span class="wf-badge ok">LISTED — đang hiển thị công khai</span></div><div class="wf-row between"><span class="wf-text">Lượt xem · lịch chờ</span><span>214 · 2 yêu cầu (xử lý → SC-27)</span></div><span class="wf-btn block">Xem yêu cầu đặt lịch (2)</span><div class="wf-row"><span class="wf-btn disabled" style="flex:1;">Sửa tin</span><span class="wf-btn ghost" style="flex:1;">Rút tin</span></div><span class="wf-small">&quot;Sửa tin&quot; disabled vì tin đã LISTED (chỉ DRAFT/REJECTED sửa được); &quot;Rút tin&quot; → confirm dialog → WITHDRAWN (không hoàn tác). Tin RESERVED/SOLD: khóa cả hai. <span class="wf-callout">17</span></span></div></div></div><div class="wf-col"><span class="wf-state-label">F · TIN SOLD (mọi người xem)</span><div class="wf-card" style="border-width:2px;border-color:var(--wf-line-strong);"><div class="pad wf-col" style="gap:8px;"><span class="wf-badge muted">ĐÃ BÁN</span><span class="wf-money lg" style="opacity:0.5;text-decoration:line-through;">1.250.000.000 ₫</span><span class="wf-text">Căn này đã hoàn tất giao dịch. Trang vẫn xem được (lịch sử) — không nhận đặt lịch.</span><span class="wf-btn block">Xem tin tương tự cùng dự án → SC-02</span></div></div><span class="wf-small">SOLD là terminal: gallery phủ mờ nhẹ, mọi CTA giao dịch ẩn, chỉ còn điều hướng sang tin khác (docs/08 §10.1).</span></div></div></div><div class="wf-legend"><div class="t">Chú thích biến thể CTA</div><ol><li><span class="num">12</span><span>Login-intent: sau đăng nhập quay lại <b>đúng tin này + đúng CTA vừa bấm</b> (deep-link return, AF-1 UC-03) — không thả user về trang chủ. <span class="ref">UC-03 AF-1</span></span></li><li><span class="num">13</span><span>KYC là điều kiện tiên quyết cho đặt lịch xem / đăng ký đấu giá / đăng tin — cùng gate `BR-KYC-08`, cùng copy `KYC_REQUIRED`. <span class="ref">BR-KYC-08</span></span></li><li><span class="num">14</span><span>Gửi lịch thành công → toast &quot;Đã gửi yêu cầu đặt lịch — chủ nhà sẽ phản hồi trong 24h&quot; + trạng thái PENDING tại SC-27. <span class="ref">FR-VW-01</span> <span class="ref">BR-VW-03</span></span></li><li><span class="num">15</span><span>Tin LISTED → RESERVED xảy ra khi ADMIN publish phiên (listing tự chuyển trạng thái) — người đang xem trang có thể thấy CTA đổi sau lần refetch kế tiếp (cache 30s). <span class="ref">FR-AU-02</span> <span class="ref">BR-AU-02</span></span></li><li><span class="num">16</span><span>Self-view: certSerial <b>masked mặc định</b> `SH-****4521`; owner có thể bấm &quot;Hiện đầy đủ&quot; (fetch `?self=true` — docs/06 §4.1). Non-owner không có đường nào thấy dù masked. <span class="ref">BR-HS-12</span> <span class="ref">docs/06 §4.1</span></span></li><li><span class="num">17</span><span>Action owner theo state machine: LISTED → withdraw được (WITHDRAWN terminal); RESERVED/SOLD → khóa mọi sửa/rút (409 `LISTING_LOCKED`). <span class="ref">BR-HS-11</span> <span class="ref">docs/08 §10.1</span></span></li></ol></div><h2 id="_5-404-—-tin-khong-kha-dung-tin-tuong-tu" tabindex="-1">5. 404 — tin không khả dụng + tin tương tự <a class="header-anchor" href="#_5-404-—-tin-khong-kha-dung-tin-tuong-tu" aria-label="Permalink to &quot;5. 404 — tin không khả dụng + tin tương tự&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:640px;"><span class="wf-state-label">TRẠNG THÁI: 404 HOUSING_NOT_FOUND (tin bị rút / link cũ)</span><div class="wf-empty"><span class="icon">🏚</span><span class="wf-title">Tin không khả dụng</span><br><span class="wf-text">Tin này đã bị rút hoặc không còn tồn tại. Gợi ý các tin tương tự cùng dự án:</span></div><div class="wf-grid" style="margin-top:12px;"><div class="wf-card"><div class="wf-img" style="min-height:100px;border-radius:0;border:none;border-bottom:1px solid var(--wf-line);"><span>ẢNH BÌA</span></div><div class="pad wf-col" style="gap:4px;"><span class="wf-title">Căn CT1-B09.03 — NOXH HP-380</span><span class="wf-text">68 m² · 2 PN · tầng 9</span><span class="wf-money">1.180.000.000 ₫</span></div></div><div class="wf-card"><div class="wf-img" style="min-height:100px;border-radius:0;border:none;border-bottom:1px solid var(--wf-line);"><span>ẢNH BÌA</span></div><div class="pad wf-col" style="gap:4px;"><span class="wf-title">Căn CT3-C02.06 — NOXH HP-380</span><span class="wf-text">66 m² · 2 PN · tầng 2</span><span class="wf-money">1.090.000.000 ₫</span></div></div></div><div class="wf-row" style="justify-content:center;margin-top:10px;"><span class="wf-btn primary">Xem tất cả tin dự án HP-380 → SC-02</span><span class="wf-btn ghost">Về trang chủ</span></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">18</span><span>404 dùng chung cho &quot;không tồn tại&quot; và &quot;không public&quot; (DRAFT/IN_REVIEW/REJECTED/WITHDRAWN) — <b>không tiết lộ</b> tin có tồn tại hay không (chống probe). &quot;Tương tự&quot; = cùng `projectId`, sort newest — quy tắc tĩnh, không AI. <span class="ref">UC-03 EF-1</span> <span class="ref">FR-HS-07</span></span></li><li><span class="num">19</span><span>Các trạng thái nền khác của màn: <b>Loading</b> = skeleton ảnh chính + 2 khối xám (thông số, panel phải); <b>Error</b> (không phải 404) = hộp lỗi + traceId + &quot;Thử lại&quot; như SC-02 mục 5. <span class="ref">docs/05 §1.4</span></span></li></ol></div><h2 id="_6-checklist-designer-khi-dung-figma-cho-sc-03" tabindex="-1">6. Checklist designer khi dựng Figma cho SC-03 <a class="header-anchor" href="#_6-checklist-designer-khi-dung-figma-cho-sc-03" aria-label="Permalink to &quot;6. Checklist designer khi dựng Figma cho SC-03&quot;">​</a></h2><ul><li>[ ] Đủ layout: desktop (2 cột — gallery/trái, panel CTA phải 320px) / tablet 768 (panel chuyển xuống dưới) / mobile 360 (carousel + CTA sticky đáy)</li><li>[ ] Đủ 6 biến thể panel CTA: Guest · KYC≠APPROVED · KYC APPROVED · RESERVED (live/upcoming) · Owner self-view · SOLD — kèm bản LISTED-đã-đóng-đăng-ký</li><li>[ ] Lightbox ảnh: counter &quot;X / N&quot;, prev/next, đóng Esc/click nền</li><li>[ ] Trạng thái tin đủ badge: ĐANG BÁN / Sắp đấu giá / ĐÃ BÁN + gallery phủ mờ khi SOLD</li><li>[ ] Giá + đơn giá /m² + trần dự án + dòng ✓ &quot;không vượt trần&quot; luôn đi cùng nhau (không số gộp)</li><li>[ ] Owner view: certSerial masked <code>SH-****4521</code> + nút &quot;Hiện đầy đủ&quot;; action Sửa/Rút đúng theo state machine (disabled + giải thích khi khóa)</li><li>[ ] 404 &quot;Tin không khả dụng&quot; + lưới tin tương tự cùng dự án (newest)</li><li>[ ] Loading skeleton · Error + traceId + Thử lại</li><li>[ ] Copy đúng docs/06 §5 (KYC_REQUIRED, VIEWING_SLOT_INVALID, VIEWING_LIMIT, AUCTION_REG_CLOSED); tiền <code>1.250.000.000 ₫</code>; ngày <code>dd/MM/yyyy HH:mm</code> GMT+7</li><li>[ ] Không emoji icon trong UI production (👤/📅/🏚 là placeholder vị trí)</li><li>[ ] Accessibility: gallery có alt text + điều hướng phím; lightbox trap focus; CTA sticky không che nội dung (safe-area bottom); contrast AA</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ (vd ẩn/hiện trường nào cho non-owner) cần PM duyệt trên docs/08 trước.</p></div>',21)])])}const f=a(l,[["render",c]]);export{r as __pageData,f as default};
